function OUT = AF7R58ZZU_ONEFILE_STAGED_PIPELINE_INSTALL()
% AF7R58ZZU
% Remove the failed MATLAB process-worker architecture and install a
% deterministic same-process cooperative replanning pipeline.
%
% Trigger contract:
%   H = exactly 4 s, unchanged.
%   Planning starts immediately when the ordinary 4-s trigger fires.
%   No extended preview and no added TTC wait threshold.
%
% Compute pipeline:
%   trigger cycle k:
%       native candidate generation for activation t_a = t_k + 2*dt
%   cycle k+1:
%       unchanged continuous REFERENCE_ONLY certificate
%       + exact canonical resource/packet/evaluator preparation
%   cycle k+2:
%       exact freshness checks + short atomic activation
%
% There is NO parpool, parfeval, backgroundPool, worker process, or thread.
% The two-period delay is computation scheduling, not a delayed trigger.
%
% At first discrete entry into H=4 s, TTC >= H-dt.  Therefore scheduled
% activation after 2*dt retains the timing lower bound H-3*dt = 3.925 s
% for dt=0.025 s.  This timing statement is separate from the continuous
% whole-body collision certificate, which remains unchanged.
%
% W1 scope remains REFERENCE_ONLY commit authority.  Execution-aware final
% authority is not silently weakened or promoted.

PRE_SHA='fb4e01fb133fab7d8d9c441d43b3ea68d9c274d20b4837ef56c25b73fd347b90';
PRE_HELPER_SHA='6dd47bb6ddf23c33c7888d8765316004abe5e622911be3a904a3c9b6f2d2aaad';
POST_SHA='aa9e2524d79739c5162ffc4d2e3a0aba533f15cae19e99313042d62f9efe57b8';

OUT=struct('schema','AF7R58ZZU_STAGED_PIPELINE_INSTALL_V1', ...
    'production_modified',false,'worker_helper_removed',false, ...
    'rollback_performed',false,'pre_sha','','post_sha','', ...
    'pre_helper_sha','','status','OPEN','error',struct());

pR=which('REPLANNING_SYSTEM');
assert(~isempty(pR)&&isfile(pR),'[AF7R58ZZU] REPLANNING_SYSTEM unresolved.');
root=fileparts(pR);
pH=fullfile(root,'af7r58zzt_process_worker.m');

outdir=tempname(root);
[ok,msg]=mkdir(outdir); assert(ok,'%s',msg);
report=fullfile(outdir,'AF7R58ZZU_REPORT.txt');
matp=fullfile(outdir,'AF7R58ZZU_OUT.mat');
backupR=fullfile(outdir,'REPLANNING_SYSTEM_PRE_AF7R58ZZU.m');
backupH=fullfile(outdir,'af7r58zzt_process_worker_PRE_AF7R58ZZU.m');

fid=fopen(report,'wt','n','UTF-8'); assert(fid>=0);
cf=onCleanup(@()safe_fclose(fid)); %#ok<NASGU>

say(fid,'====================================================================================================');
say(fid,' AF7R58ZZU | DETERMINISTIC STAGED REPLAN PIPELINE INSTALL');
say(fid,'====================================================================================================');
say(fid,'[REMOVE] MATLAB process worker/parfeval architecture = 1');
say(fid,'[TRIGGER] fixedH4s=1 | immediateOrdinaryTrigger=1 | extendedPreview=0');
say(fid,'[PIPELINE] stage1Generate=1 | stage2CertPrepare=1 | stage3Atomic=1');
say(fid,'[SCHEDULE] activation=t_trigger+2dt | dt=25ms nominal');
say(fid,'[SAFETY] staleReject=1 | continuousCertificateMathChanged=0 | finiteSensingChanged=0');

writeR=false;
helperDeleted=false;

try
    pre=file_hash(pR);
    OUT.pre_sha=pre;
    assert(strcmp(pre,PRE_SHA), ...
        '[AF7R58ZZU] current source is not exact AF7R58ZZT-R2 authority.');

    assert(isfile(pH), ...
        '[AF7R58ZZU] expected ZZT process-worker helper is missing.');
    preH=file_hash(pH);
    OUT.pre_helper_sha=preH;
    assert(strcmp(preH,PRE_HELPER_SHA), ...
        '[AF7R58ZZU] current worker helper differs from exact ZZT-R2 authority.');

    stage=fullfile(outdir,'STAGE');
    [ok,msg]=mkdir(stage); assert(ok,'%s',msg);

