'YCDWZHHGbJPkDdv5xGYF0E2mDzSn1HzqXCbgCcyQCTNknpytminzww6Yf2NxBJbNlVOl4kMgs3l52g/XBDY3dfXq5PL4iLmikD+oCKIPAkVQSLUe3gzVhbXR' ...
'n46Y1fRKta56daJLq6V/iQKqm7ViRNEDFD2Goueh6B0GBfR9os5Q1D0U9SQUKVhd3UZXDWh1kOxJdOCuXACZt5o+yXb3JJKYfJWRe7fqE2q56pEf7NNABpn1' ...
'h7yG9kINfZw1tJe5ob1wQ3uBhlbua0PrakhhhGPqNbeeubn1cHPrgeaOZ2uu+3DIrkDliP2kWiqWUpc5PX7IPWkKJDl+mFJczl8aLctpJfAIYv1MX94wLO74' ...
'pAGvWoZ2uXrIATvkQLq6j5JMVTSlFdiBJ6Fix5jprGNIIKY2IAOYqkIpMzRlH80ZMpIMCw5uKpIKQ1IRIOmY6Q0ZZzjGBThwIrKovJ7i3NPhA/z3/wIVCjgm' ...
'gVcKAA=='
    };
    gzR=matlab.net.base64decode([B64R{:}]);
    gzPath=fullfile(stage,'REPLANNING_SYSTEM.m.gz');
    fz=fopen(gzPath,'wb'); assert(fz>=0);
    fwrite(fz,uint8(gzR),'uint8'); fclose(fz);
    gunzip(gzPath,stage);
    stagedR=fullfile(stage,'REPLANNING_SYSTEM.m');
    assert(strcmp(file_hash(stagedR),POST_SHA), ...
        '[AF7R58ZZU] staged candidate SHA mismatch.');

    R=read_utf8(stagedR);

    % Architecture/source invariants BEFORE any production write.
    assert(count_exact(R,'horizon_s     = 4.0;')==1);
    assert(~contains(R,'prepare_early_intervention_reference_cache'));
    assert(~contains(R,'process_worker_'));
    assert(~contains(R,'parfeval'));
    assert(~contains(R,'parpool'));
    assert(~contains(R,'backgroundPool'));
    assert(count_exact(R,'ENABLE_STAGED_REPLAN_PIPELINE = true;')==1);
    assert(contains(R,'ta=t_now+2*dt;'));
    assert(contains(R,'candidate=obj.af7r46_single_core_proposal_compact(CTX);'));
    assert(contains(R,'obj.evaluate_reference_only_proposal_certificate(P);'));
    assert(contains(R,'af7r58i_prepare_batch_model( ...'));
    assert(contains(R,'AF7R58ZZU_PREPARED_COMMIT_V1'));
    assert(contains(R,'PIPELINE_SOURCE_OR_SENSOR_STALE'));
    assert(contains(R,'The generator receives ONLY sensor-known obstacles:'));
    assert(contains(R,'''detected_only_obstacle_contract'',true'));
    assert(contains(R,'Initial known set is empty.'));
    assert(contains(R,'raw_sensor_gate alone may admit a previously unknown obstacle.'));
    assert(contains(R,'RAW=af7r36_single_core_mex(1,pkt);'));

    % Historical 4-ms physical stop/fallback quantity remains present;
    % normal staged acceptance is based on the 25-ms control period.
    assert(count_exact(R,'hard_modify_deadline_s = 0.004;')==1);
    assert(contains(R,'attempt_budget_s=double(obj.prediction_dt);'));

    % Parse the ENTIRE patched class under an alternate class name before
    % touching production.
    parseDir=fullfile(outdir,'PARSE');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZZU_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(R,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    assert(~strcmp(parseText,R),'[AF7R58ZZU] class rename failed.');
    parsePath=fullfile(parseDir,[parseName '.m']);
    write_utf8(parsePath,parseText);
    addpath(parseDir,'-begin');
    cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZZU] patched class parse failed.');
    eval(['clear ' parseName]);

    say(fid,'');
    say(fid,'[A. PREFLIGHT]');
    say(fid,' exact ZZT-R2 source PRE                 = 1 | %s',pre);
    say(fid,' exact ZZT-R2 worker helper PRE          = 1 | %s',preH);
    say(fid,' fixed collision horizon H=4 s           = 1');
    say(fid,' extended preview                        = 0');
    say(fid,' MATLAB process/thread worker tokens     = 0');
    say(fid,' staged activation                       = t_trigger + 2*dt');
    say(fid,' first-entry activation TTC LB @25ms dt  = 3.925 s');
    say(fid,' native generator retained               = 1');
    say(fid,' continuous reference certificate retained=1');
    say(fid,' finite-sensing contract retained        = 1');
    say(fid,' whole class parse                       = 1');
    say(fid,' production writes                       = 0');

    copyfile(pR,backupR,'f');
    copyfile(pH,backupH,'f');

    writeR=true;
    copyfile(stagedR,pR,'f');
    post=file_hash(pR);
    assert(strcmp(post,POST_SHA),'[AF7R58ZZU] production POST SHA mismatch.');

    delete(pH);
    helperDeleted=true;
    assert(~isfile(pH),'[AF7R58ZZU] failed to remove process-worker helper.');

    OUT.production_modified=true;
    OUT.worker_helper_removed=true;
    OUT.post_sha=post;
    OUT.status='STAGED_PIPELINE_INSTALLED__PROCESS_WORKER_REMOVED__CLEAN_RERUN_REQUIRED';

    say(fid,'');
    say(fid,'[B. INSTALL]');
    say(fid,' REPLANNING_SYSTEM post SHA = %s',post);
    say(fid,' process-worker helper removed = 1');
    say(fid,' status = %s',OUT.status);

catch ME
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});
    try
        if writeR && isfile(backupR)
            copyfile(backupR,pR,'f');
        end
        if helperDeleted
            copyfile(backupH,pH,'f');
        end
        OUT.rollback_performed=writeR||helperDeleted;
    catch
    end
    OUT.production_modified=false;
    OUT.worker_helper_removed=false;
    OUT.status='INSTALL_FAILED__ROLLBACK_ATTEMPTED';

    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier = %s',ME.identifier);
    say(fid,' message    = %s',ME.message);
    say(fid,' rollback   = %d',OUT.rollback_performed);
end

OUT.report_path=report;
OUT.mat_path=matp;
save(matp,'OUT','-v7');
assignin('base','AF7R58ZZU_OUT',OUT);
say(fid,'');
say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',matp);
say(fid,'status = %s',OUT.status);
end

function n=count_exact(s,pat)
n=numel(strfind(s,pat));
end

function s=read_utf8(path)
fid=fopen(path,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,'*uint8');
s=native2unicode(b.','UTF-8');
end

function write_utf8(path,s)
b=unicode2native(s,'UTF-8');
fid=fopen(path,'wb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,uint8(b),'uint8');
end

function h=file_hash(path)
md=java.security.MessageDigest.getInstance('SHA-256');
fid=fopen(path,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
while true
    b=fread(fid,1024*1024,'*uint8');
    if isempty(b), break; end
    md.update(b);
end
u=typecast(md.digest(),'uint8');
h=lower(reshape(dec2hex(u,2).',1,[]));
end

function say(fid,varargin)
fprintf(fid,[varargin{1} '\n'],varargin{2:end});
fprintf([varargin{1} '\n'],varargin{2:end});
end

function safe_rmpath(p)
try, rmpath(p); catch, end
end

function safe_fclose(fid)
try, fclose(fid); catch, end
end
